/// <summary>
/// Runs the full four-phase flow for a set of deals, in strict sequence, in the current thread.
/// </summary>
public static void runForDeals(
    container _dealRecIds,
    TAMRebateFromDate _from,
    TAMRebateToDate _to,
    TransDate _transDate,
    boolean _processRebate,
    boolean _processWriteOff)
{
    if (_processRebate)
    {
        // Single-thread whole-selection path: scope by deal (the deal variant handles a deal's
        // reconcile-by-line tables internally).
        METRebateCombinedFlow::createTrans(TAMRebateTransactionType::Rebate, tableNum(TAMRebateDeal), _dealRecIds, _from, _to);
        METRebateCombinedFlow::post(TAMRebateTransactionType::Rebate, METRebateCombinedSplitTask::getDealsToPost(_dealRecIds), _from, _to, _transDate);
    }

    if (_processWriteOff)
    {
        // Standard excludes RebateOutputType::Item for non-Rebate types (see controller.updateQueryRebateOutputType).
        container writeOffDeals = METRebateCombinedFlow::filterNonItemOutput(_dealRecIds);
        if (conLen(writeOffDeals) > 0)
        {
            METRebateCombinedFlow::createTrans(TAMRebateTransactionType::WriteOff, tableNum(TAMRebateDeal), writeOffDeals, _from, _to);
            METRebateCombinedFlow::post(TAMRebateTransactionType::WriteOff, METRebateCombinedSplitTask::getDealsToPost(writeOffDeals), _from, _to, _transDate);
        }
    }
}

/// <summary>
/// Runs create-trans inline for the given records. <c>_tableId</c> selects the engine variant:
/// tableNum(TAMRebateDeal) processes whole deals (used for reconcile-by-deal, and for the
/// single-thread whole-selection path); tableNum(TAMRebateTable) processes individual rebate
/// tables/lines (used to parallelize reconcile-by-line deals at line granularity).
/// </summary>
public static void createTrans(
    TAMRebateTransactionType _type,
    TableId _tableId,
    container _recIds,
    TAMRebateFromDate _from,
    TAMRebateToDate _to)
{
    TAMRebateCreateTransContract c = TAMRebateCreateTransContract::construct();
    c.parmRebateTransactionType(_type);
    c.parmFromDate(_from);
    c.parmToDate(_to);
    c.parmPackedRecords(_recIds);
    c.parmTableId(_tableId);

    // Force INLINE execution: the contract getter coerces any value <= 0 to 8, so we must
    // explicitly set 1 to keep processRebateTrans's '> 1' guard false and avoid a nested split.
    c.parmMaxBatchTaskNum(1);

    TAMRebateCreateTrans::processRebateTrans(c);
}

public static void post( TAMRebateTransactionType _type, container _dealRecIds, TAMRebateFromDate _from, TAMRebateToDate _to, TransDate _transDate) { int days = abs(_to - _from);
_to = days <= 7 ? dateEndWk(_to) : dateEndMth(_to);
TAMRebatePostContract p = TAMRebatePostContract::newFromParameters( _type, _from, _to, _transDate, false, // postGuarantee dateNull(), // guaranteeFromDate dateNull(), // guaranteeToDate _dealRecIds, // packed deal RecIds true, // hideGuaranteePosting '', // packedQuery (none - using packed records) tableNum(TAMRebateDeal), false, // useOriginalTransactionType false); // isCancelling
TAMRebatePost::postRebate(p); }

/// <summary>
/// Enumerate the selected deals from the dialog query (empty query =&gt; all deals) in a single
/// pass, capturing each deal's <c>RebateReconciliation</c> so the split does not re-query it
/// per deal. Returns a Map of deal RecId -&gt; reconciliation (as int).
/// </summary>
public static Map enumerateDeals(str _packedQuery)
{
    Query q;
    container qc = SysOperationHelper::base64Decode(_packedQuery);
    q = qc ? new Query(qc) : new Query(queryStr(METRebateCombinedDeals));

    Map deals = new Map(Types::Int64, Types::Integer);
    QueryRun qr = new QueryRun(q);
    while (qr.next())
    {
        TAMRebateDeal deal = qr.get(tableNum(TAMRebateDeal));
        deals.insert(deal.RecId, enum2int(deal.RebateReconciliation));
    }

    return deals;
}

/// <summary>
/// The deal RecIds of an <c>enumerateDeals</c> map, as a container (for the post/single-thread
/// paths that only need the RecId list).
/// </summary>
public static container dealRecIds(Map _deals)
{
    container recIds;
    MapEnumerator me = _deals.getEnumerator();
    while (me.moveNext())
    {
        recIds += me.currentKey();
    }

    return recIds;
}

public static container filterNonItemOutput(container _dealRecIds)
{
    container result;
    for (int i = 1; i <= conLen(_dealRecIds); i++)
    {
        RefRecId dealRecId = conPeek(_dealRecIds, i);
        TAMRebateDeal deal;
        select firstOnly RecId, RebateOutputType from deal
            where deal.RecId == dealRecId
               && deal.RebateOutputType != TAMRebateOutputType::Item;
        if (deal.RecId)
        {
            result += dealRecId;
        }
    }

    return result;
}
